  `},dm={components:{RouteHeader:X,IconGlyph:J},data(){return{view:"home",activeTask:null,error:"",scoreDraft:{performance:"",collaboration:"",integrity:"",suggestion:""},tasks:[{id:"EV-2026-01",title:"2026 年班组长履职测评",target:"发动机车间班组长",deadline:"06月28日 17:00",status:"待完成"},{id:"EV-2026-02",title:"班组建设满意度测评",target:"发动机车间员工",deadline:"07月05日 17:00",status:"待完成"}]}},methods:{back(){if(this.activeTask){this.activeTask=null,this.error="";return}if(this.view!=="home"){this.view="home";return}this.$emit("back")},openTask(e){this.activeTask=e,this.error="",this.scoreDraft={performance:"",collaboration:"",integrity:"",suggestion:""}},submit(){if(!this.scoreDraft.performance||!this.scoreDraft.collaboration||!this.scoreDraft.integrity){this.error="请完成全部评分项";return}this.activeTask.status="已完成",this.$emit("notify","测评已提交"),this.activeTask=null,this.view="tasks"}},template:`
